<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useRoute}from'vue-router';import{interviewApi}from'../api/modules';const route=useRoute(),record=ref<any>(),loading=ref(true),error=ref('');const report=computed(()=>{try{return record.value?JSON.parse(record.value.reportJson):null}catch{return null}});async function load(){loading.value=true;try{record.value=await interviewApi.report(String(route.params.id))}catch(e){error.value=(e as Error).message}finally{loading.value=false}}onMounted(load)</script>
<template><section class="page-head"><div><h2>面试报告</h2><p>综合分取本次逐题真实评分均值，内容由本次问答生成。</p></div></section><div v-if="loading" class="state-card">加载报告中</div><div v-else-if="error" class="state-card error">{{error}} <button @click="load">重试</button></div><template v-else-if="report"><section class="report-summary"><article class="panel report-score"><small>综合得分</small><strong>{{Math.round(report.overallScore)}}</strong><span>{{record.createdAt}}</span></article><article class="panel dimensions"><h3>能力维度</h3><div v-for="(score,name) in report.dimensions" :key="name"><span>{{name}} <b>{{score}}</b></span><i><em :style="{width:`${score}%`}"/></i></div></article></section><section class="report-columns"><article class="panel result-block"><h3>优势</h3><p v-for="s in report.strengths">{{s}}</p></article><article class="panel result-block"><h3>薄弱知识点</h3><p v-for="s in report.weakPoints">{{s}}</p></article><article class="panel result-block"><h3>改进建议</h3><p v-for="s in report.suggestions">{{s}}</p></article></section><section class="panel data-list"><div class="panel-title"><h3>逐题详情</h3><small>{{report.questionDetails?.length||0}} 题</small></div><details v-for="(q,i) in report.questionDetails" :key="q.id" class="answer-detail"><summary><b>{{Number(i)+1}}. {{q.questionText}}</b><span>{{Math.round(q.score)}} 分</span></summary><h4>我的回答</h4><p>{{q.answerText}}</p><h4>模型评价</h4><pre>{{JSON.stringify(JSON.parse(q.evaluationJson),null,2)}}</pre></details></section></template></template>
